NS_IMETHODIMP
nsMsgBrkMBoxStore::GetSupportsCompaction(bool* aSupportsCompaction) {
  NS_ENSURE_ARG_POINTER(aSupportsCompaction);
  *aSupportsCompaction = true;
  return NS_OK;
}

NS_IMETHODIMP nsMsgBrkMBoxStore::AsyncCompact(
    nsIMsgFolder* folder, nsIStoreCompactListener* compactListener,
    bool patchXMozillaHeaders) {
  nsCOMPtr<nsIFile> srcMbox;
  nsresult rv = folder->GetFilePath(getter_AddRefs(srcMbox));
  NS_ENSURE_SUCCESS(rv, rv);

  // Fire and forget. MboxScanner will hold itself in existence until finished.
  RefPtr<MboxCompactor> compactor = new MboxCompactor();
  return compactor->BeginCompaction(srcMbox, compactListener,
                                    patchXMozillaHeaders);
}

// The msgStore will hold us in existence until our OnFinalSummary()
// handler returns.
//
// After AsyncCompact() is called, we'll receive callbacks to:
// OnCompactionBegin()    - At the start of the compaction.
// OnRetentionQuery()     - For each message, we give a thumbs up or down.
// OnMessageRetained()    - After each kept message has been written.
// OnCompactionComplete() - The new mbox is ready to go, so we should
//                          install the new db.
// OnFinalSummary()       - At the end of the compaction.
nsCOMPtr<nsIMsgPluggableStore> msgStore;
rv = mFolder->GetMsgStore(getter_AddRefs(msgStore));
NS_ENSURE_SUCCESS(rv, rv);
rv = msgStore->AsyncCompact(mFolder, this, patchXMozillaHeaders);
NS_ENSURE_SUCCESS(rv, rv);

